<?php
require __DIR__.'/bootstrap.php';if(!is_file(__DIR__.'/config.php')){header('Location: install.php');exit;}$error='';
try{$db=db();if(currentUser($db)){header('Location: index.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){csrf();$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';$ip=hash('sha256',$_SERVER['REMOTE_ADDR']??'unknown');$db->beginTransaction();$q=$db->prepare('INSERT IGNORE INTO karban_login_attempts VALUES(?,0,?)');$q->execute([$ip,time()]);$q=$db->prepare('SELECT * FROM karban_login_attempts WHERE ip_hash=? FOR UPDATE');$q->execute([$ip]);$a=$q->fetch();if(time()-(int)$a['window_start']>900){$a['attempts']=0;$a['window_start']=time();}if((int)$a['attempts']>=10){$db->commit();$error='تلاش‌های ورود زیاد است. ۱۵ دقیقه دیگر امتحان کنید.';}else{$q=$db->prepare('SELECT * FROM karban_users WHERE email=?');$q->execute([$email]);$u=$q->fetch();if($u&&password_verify($password,$u['password_hash'])){$q=$db->prepare('DELETE FROM karban_login_attempts WHERE ip_hash=?');$q->execute([$ip]);$db->commit();session_regenerate_id(true);$_SESSION['uid']=$u['id'];$_SESSION['csrf']=bin2hex(random_bytes(32));header('Location: index.php');exit;}else{$q=$db->prepare('UPDATE karban_login_attempts SET attempts=?,window_start=? WHERE ip_hash=?');$q->execute([(int)$a['attempts']+1,$a['window_start'],$ip]);$db->commit();$error='ایمیل یا رمز عبور اشتباه است.';}}}}
catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();$error='ارتباط با دیتابیس برقرار نشد.';}
page('ورود به کاربان','<p>مدیریت پروژه‌ها و کارهای تیم، در یک فضای مشترک.</p>'.($error?'<p class="error">'.esc($error).'</p>':'').'<form method="post"><input type="hidden" name="csrf" value="'.esc($_SESSION['csrf']).'"><label>ایمیل<input type="email" name="email" required autocomplete="username" dir="ltr"></label><label>رمز عبور<input type="password" name="password" required autocomplete="current-password"></label><button>ورود</button></form>');
